import{basename}from"node:path";import yargs from"yargs/yargs";import{hideBin}from"yargs/helpers";import{Text2ImagePipeline}from"openvino-genai-node";import{saveAsBMP}from"../image_utils.js";async function main(){const e=await yargs(hideBin(process.argv)).scriptName(basename(process.argv[1])).command("$0 <model_dir> <prompt>","Decode and save the intermediate image at every denoising step",(e=>e.positional("model_dir",{type:"string",describe:"Path to the converted image generation model directory",demandOption:!0}).positional("prompt",{type:"string",describe:"Prompt to generate images from",demandOption:!0}))).strict().help().parse(),t=await Text2ImagePipeline(e.model_dir,"CPU"),i=[];await t.generate(e.prompt,{width:512,height:512,num_inference_steps:20,num_images_per_prompt:1,rng_seed:42,callback:async function(e,o,r){return i.push(await t.decode(r)),process.stdout.write(`Step ${e+1}/${o}\r`),!1}});for(let o=0;o<i.length;o++)await saveAsBMP(`denoising_step_${o}.bmp`,i[o]);console.log(`\nSaved ${i.length} denoising step images.`)}main().catch((e=>{console.error(e),process.exitCode=1}));